mapper.select:
SELECT *
FROM tms_risk_monitoring
WHERE isin = #{isin} AND reporting_date = #{reportingDate}

SELECT DISTINCT t.isin
FROM tms_trade_blotter t
WHERE t.isin IS NOT NULL
AND t.isin != ''
AND t.value_date <= #{reportingDate}
AND t.maturity_date >= #{reportingDate}
AND NOT EXISTS (
    SELECT 1 FROM tms_risk_monitoring r
    WHERE r.isin = t.isin
    AND r.reporting_date = #{reportingDate}
)

SELECT DISTINCT r.isin
FROM tms_risk_monitoring r
WHERE r.reporting_date = #{reportingDate}
AND NOT EXISTS (
    SELECT 1 FROM tms_trade_blotter t
    WHERE t.isin = r.isin
    AND t.value_date <= #{reportingDate}
    AND t.maturity_date >= #{reportingDate}
)
